use crate::ArtifactRef;
use semio_framework_value::{RetirementDemand, RetainedCloneGrant, retained_clone::RetainedCloneSource};
use semio_framework_value_persistent::retained_equality::RetainedEqualityOwner;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(257),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source(value:ArtifactRef)->RetainedCloneSource<ArtifactRef>{let d=RetainedCloneSource::<ArtifactRef>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<ArtifactRef>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).map_err(|(e,..)|e).unwrap().0}
fn parse(value:&serde_json::Value)->ArtifactRef{use semio_framework_value::FromValue;ArtifactRef::from_value(serde_json::from_value(value.clone()).unwrap()).unwrap()}
fn pointers(value:&ArtifactRef)->[*const u8;4]{[value.artifact_id.as_ptr(),value.dialect.artifact_kind.as_ptr(),value.dialect.standard.as_ptr(),value.dialect.subset.as_ptr()]}
fn source_close(source:&mut RetainedCloneSource<ArtifactRef>){while !source.terminal_is_empty(){let g=grant(source.next_close_demand(4096).unwrap());assert!(source.close_step(g).unwrap().progress().fits(g));}}
fn close(owner:&mut RetainedEqualityOwner<ArtifactRef>,mut born:usize,mut released:usize){owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(4096).unwrap();let g=grant(d);assert_eq!(owner.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());if d.release_bytes>0{assert_eq!(owner.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}).unwrap().progress(),Default::default());}let p=owner.close_step(g).unwrap().progress();assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;}assert_eq!(born,released);}
#[test]
fn original_artifact_reference_equality_preserves_all_exact_identity_fields(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut left=source(parse(&row["left"]));let mut right=source(parse(&row["right"]));let original=pointers(left.borrow().get());let mut owner=RetainedEqualityOwner::<ArtifactRef>::new();let(mut born,mut released,mut turns)=(0,0,0);while owner.result().is_none(){let d=owner.demand(left.borrow(),right.borrow(),257).unwrap();let g=grant(d);assert_eq!(owner.advance(left.borrow(),right.borrow(),RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}).unwrap().progress,Default::default());if d.capacity_bytes>0{assert_eq!(owner.advance(left.borrow(),right.borrow(),RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}).unwrap().progress,Default::default());}let p=owner.advance(left.borrow(),right.borrow(),g).unwrap().progress;assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;turns+=1;assert!(turns<10000);}assert_eq!(owner.result(),row["equal"].as_bool());assert_eq!(left.borrow().get()==right.borrow().get(),row["equal"].as_bool().unwrap());close(&mut owner,born,released);assert_eq!(pointers(left.borrow().get()),original);drop(owner);source_close(&mut left);source_close(&mut right);eprintln!("[DEBUG] Original ArtifactRef {:?} four exact owned fields match native typed equality and neutral oracle",row["id"]);}}
#[test]
fn original_artifact_reference_equality_cancellation_keeps_source_and_cursor_custody(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap(){let mut left=source(parse(&row["left"]));let mut right=source(parse(&row["right"]));let mut foreign=source(parse(&row["left"]));let original=pointers(right.borrow().get());let mut owner=RetainedEqualityOwner::<ArtifactRef>::new();let(mut born,mut released,mut turns)=(0,0,0);while owner.result().is_none()&&turns<cut.as_u64().unwrap()as usize{let g=grant(owner.demand(left.borrow(),right.borrow(),257).unwrap());let p=owner.advance(left.borrow(),right.borrow(),g).unwrap().progress;assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;turns+=1;}if turns>0{assert!(owner.verify(foreign.borrow(),right.borrow()).is_err());}close(&mut owner,born,released);assert_eq!(pointers(right.borrow().get()),original);drop(owner);source_close(&mut left);source_close(&mut right);source_close(&mut foreign);eprintln!("[DEBUG] Original ArtifactRef {:?} partial cut={cut} retains original fields and child-first cursor credits",row["id"]);}}}
